82	    private String membershipNumber;
83	
84	    @Column(name = "possible_duplicate")
85	    private Boolean possibleDuplicate;
86	
87	    @Column(name = "possible_duplicate_of")
88	    private Integer possibleDuplicateOf;
89	
90	    @Column(name = "deleted", nullable = false)
91	    private boolean deleted = false;
92	
93	    /**
94	     * The number of owners belonging to this owner's household (owners sharing the same
95	     * {@code householdId}), including this owner. It is a derived, non-persistent value populated
96	     * when an owner is mapped for a response.
97	     */
98	    @Transient
99	    private Integer householdMemberCount;
100	
101	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
102	    private Set<Pet> pets;
