362	        int sum = 0;
363	        boolean dbl = true;
364	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
365	            char c = this.customerCode.charAt(i);
366	            if (c < '0' || c > '9') {
367	                continue;
